import os
from google.cloud import texttospeech_v1

def list_voices_for_locale(locale: str):
    """List available voices for a given locale using Google Cloud Text-to-Speech API."""
    client = texttospeech_v1.TextToSpeechClient()

    # List voices request with language code filter
    response = client.list_voices(language_code=locale)

    voices = []
    for voice in response.voices:
        voices.append({
            "name": voice.name,
            "ssml_gender": texttospeech_v1.SsmlVoiceGender(voice.ssml_gender).name,
            "language_codes": voice.language_codes
        })

    return voices

def select_voice_for_locale(locale: str, gender: str = None):
    """Select a voice for a given locale and optional gender using Google Cloud Text-to-Speech API."""
    client = texttospeech_v1.TextToSpeechClient()

    response = client.list_voices(language_code=locale)

    for voice in response.voices:
        if gender and texttospeech_v1.SsmlVoiceGender(voice.ssml_gender).name != gender.upper():
            continue
        return {
            "name": voice.name,
            "ssml_gender": texttospeech_v1.SsmlVoiceGender(voice.ssml_gender).name,
            "language_codes": voice.language_codes
        }

    return None
